#include "../asmr_lab_math.h"
#include "../source_model.h"
#include <cassert>
#include <cmath>
#include <cstdio>
#include <vector>

// The ASMR lab's binaural sound is not generated by an HRTF/pan matrix.
// A real pressure field must propagate from the mouth across physical
// space, interact with the head obstacle, and arrive at two ears
// at different times and levels. This CPU reference uses exactly
// the stencil and material model from asmrPressureStep (CUDA).
struct EarEnergy {
    double left=0,right=0;
    int firstLeft=-1,firstRight=-1;
};
static EarEnergy propagate(asmr::Vec2 artist){
    constexpr float dx=0.01f;
    const int n=asmr::cells(dx);
    const auto mask=asmr::roomMask(n,dx);
    std::vector<float> previous((size_t)n*n,0),now(previous),next(previous);
    const auto mouth=asmr::mouth(artist);
    assert(asmr::probeInAir(mask,n,mouth,dx));
    const float gx=mouth.x/dx-0.5f,gy=mouth.y/dx-0.5f;
    const float lx=asmr::leftEar().x/dx-0.5f;
    const float rx=asmr::rightEar().x/dx-0.5f;
    const float ey=asmr::kListenerY/dx-0.5f;
    const int pulseDuration=std::lround(
        echo::kClickDurationSeconds/(float)asmr::stepSeconds(dx));
    EarEnergy energy;
    for(int t=0;t<240;++t) {
        for(int y=1;y<n-1;++y)for(int x=1;x<n-1;++x){
            const int idx=y*n+x;
            if(mask[idx]>0){next[idx]=0;continue;}
            const float centre=now[idx];
            const float left=mask[idx-1]>0?centre:now[idx-1];
            const float right=mask[idx+1]>0?centre:now[idx+1];
            const float below=mask[idx-n]>0?centre:now[idx-n];
            const float above=mask[idx+n]>0?centre:now[idx+n];
            const float damping=echo::mixedWallDamping(
                mask[idx-1],mask[idx+1],mask[idx-n],mask[idx+n],
                asmr::kHeadReflection,echo::kCourant);
            float pressure=echo::impedanceWaveStep(
                centre,previous[idx],left,right,below,above,
                echo::kCourantSquared,damping);
            if(std::fabs(x-gx)<1 && std::fabs(y-gy)<1)
                pressure+=echo::clickSample(t,pulseDuration,
                        (float)asmr::stepSeconds(dx))*
                    echo::sourceWeight(gx,gy,x,y);
            next[idx]=pressure*std::exp(-0.6f*(float)asmr::stepSeconds(dx));
        }
        previous.swap(now);now.swap(next);
        const float l=echo::bilinearSample(now.data(),n,lx,ey);
        const float r=echo::bilinearSample(now.data(),n,rx,ey);
        assert(std::isfinite(l)&&std::isfinite(r));
        energy.left+=l*l;
        energy.right+=r*r;
        // Finite amplitude arrival can't occur before a wave has
        // physically propagated from source through the grid.
        if(energy.firstLeft<0 && std::fabs(l)>1e-6f)
            energy.firstLeft=t;
        if(energy.firstRight<0 && std::fabs(r)>1e-6f)
            energy.firstRight=t;
    }
    return energy;
}
int main(){
    const auto right=propagate({1.48f,1.0f});
    const auto left=propagate({0.52f,1.0f});
    assert(right.firstRight>=0&&right.firstLeft>=0);
    assert(left.firstLeft>=0&&left.firstRight>=0);
    assert(right.firstRight<right.firstLeft);
    assert(left.firstLeft<left.firstRight);
    assert(right.right>right.left);
    assert(left.left>left.right);
    // The geometry and FDTD stencil are symmetric about the
    // listener: swapping source side swaps the ear response.
    assert(std::fabs(right.right-left.left)<
           0.15*(right.right+left.left));
    std::printf("Physical FDTD ear propagation: RIGHT source L=%.4g R=%.4g, "
                "LEFT source L=%.4g R=%.4g; actual obstacle shadow & time-delay passed\n",
                right.left,right.right,left.left,left.right);
}
